int main(){try{Fixture f;check(take(political_dismissal_source_selected_version({}))==0,"old world no new module");check(!political_dismissal_source_selected_version({{political_dismissal_sources_module,"1"}}).ok,"source module requires original politics and life contract");std::vector<std::pair<StableId,StableId>> modules{{"politics","1"},{"family_life","1"},{political_dismissal_sources_module,"1"}};check(take(political_dismissal_source_selected_version(modules))==1,"explicit selected sidecar");PoliticalDismissalSourceState state;check(validate_political_dismissal_source_layout(f.common,modules,&state).ok,"exact module/state pair");check(!validate_political_dismissal_source_layout(f.common,modules,nullptr).ok,"selected missing state refused");check(!validate_political_dismissal_source_layout(f.common,{},&state).ok,"hidden state without module refused");modules.push_back(modules.back());check(!political_dismissal_source_selected_version(modules).ok,"duplicate source module refused");modules.pop_back();modules.back().second="2";check(!political_dismissal_source_selected_version(modules).ok,"unknown source version refused");auto old=f.remove();check(validate_political_dismissal_source_layout(f.common,{},nullptr).ok,"unselected original dismissal facts retain old layout");const auto fake=take(f.common.next_id("political_dismissal_sources"));take(f.common.append_fact({fake,"forged",political_dismissal_sources_module}));check(!validate_political_dismissal_source_layout(f.common,{},nullptr).ok,"sidecar cannot add unowned Common facts");std::cout<<checks<<" dismissal profile checks; no World\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
